const crypto = require('node:crypto');

function totp(secret, step = Math.floor(Date.now() / 30000)) {
  const h = crypto.createHmac('sha1', secret).update(String(step)).digest();
  return String(h.readUInt32BE(h[h.length - 1] & 0xf) % 1000000).padStart(6, '0');
}

module.exports = { totp };
