const test = require('node:test');
const assert = require('node:assert');
const session = require('../src/session');

test('idle sessions expire after two hours', () => {
  const sid = session.create({ id: 'u1', role: 'member' }, 0);
  assert.strictEqual(session.check(sid, session.IDLE_MS + 1), null);
});

test('admin sessions end twelve hours after sign-in, even when active', () => {
  const sid = session.create({ id: 'a1', role: 'admin' }, 0);
  for (let t = 3600000; t <= 11 * 3600000; t += 3600000) assert.ok(session.check(sid, t));
  assert.strictEqual(session.check(sid, 12 * 3600000 + 1), null);
});
